@php
$ganttTasks=$board->columns->flatMap(fn($column)=>$column->cards)->map(fn($task)=>['id'=>$task->id,'title'=>$task->title,'start'=>$task->start_date?->toDateString(),'due'=>$task->due_date?->toDateString(),'done'=>(bool)$task->completed_at,'assignees'=>$task->assignees->pluck('id')->map(fn($id)=>(string)$id)->all(),'labels'=>$task->labels->pluck('id')->map(fn($id)=>(string)$id)->all(),'search'=>mb_strtolower($task->title.' '.$task->description)])->values()->all();
@endphp
<section x-show="boardView==='gantt'" x-cloak class="notes-card mb-4" x-data="taskGantt(@js($ganttTasks))">
<div class="folder-panel-head"><div><h2>Gantt timeline</h2><p class="notes-hint">Start and due dates define scheduled bars. A single date is a milestone; tasks without dates remain unscheduled.</p></div><div class="notes-actions"><button type="button" class="form-chip" @click="shift(-14)">Previous</button><input type="date" class="theme-input" x-model="anchor" aria-label="Gantt start date"><button type="button" class="form-chip" @click="shift(14)">Next</button></div></div>
<div class="task-gantt-scroll"><div style="min-width:1280px"><div class="task-gantt-row"><strong>Task / schedule</strong><div class="task-gantt-days"><template x-for="day in days" :key="day"><span x-text="day.slice(8)" :title="day"></span></template></div></div><template x-for="task in visibleTasks" :key="task.id"><div class="task-gantt-row"><button type="button" @click="openCard(task.id)" class="text-left"><strong x-text="task.title"></strong><small x-text="task.start&&task.due?task.start+' → '+task.due:((task.due||task.start)?'Milestone: '+(task.due||task.start):'Unscheduled')"></small></button><div class="task-gantt-track"><button type="button" class="task-gantt-bar" x-show="bar(task)" :style="bar(task)" @click="openCard(task.id)" :title="task.title+' · '+(task.done?'Completed':'Open')" :class="task.done?'is-complete':''"><span x-text="task.done?'✓':'●'"></span></button><span class="notes-hint" x-show="!task.start&&!task.due">No dates set</span></div></div></template></div></div><p class="notes-hint mt-3" x-show="!visibleTasks.length">No matching tasks. Clear filters or add a task to the board.</p>
</section>
<style>
.task-workspace-toolbar{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin-bottom:20px}.task-gantt-scroll{overflow-x:auto}.task-gantt-row{display:grid;grid-template-columns:280px 980px;align-items:center;border-bottom:1px solid var(--border-strong);min-height:60px}.task-gantt-row>button,.task-gantt-row>strong{padding:12px}.task-gantt-row small{display:block;font-size:11px;color:var(--text-muted);margin-top:6px}.task-gantt-days{display:grid;grid-template-columns:repeat(35,28px);font-size:10px}.task-gantt-days span{text-align:center;border-left:1px solid var(--border-strong);padding:12px 0}.task-gantt-track{height:40px;position:relative;background:repeating-linear-gradient(90deg,transparent 0,transparent 27px,var(--border-strong) 27px,var(--border-strong) 28px)}.task-gantt-bar{position:absolute;top:8px;height:24px;border-radius:7px;background:#4367ed;color:white;min-width:12px;font-size:11px}.task-gantt-bar.is-complete{background:#0b9273}
</style>
<script>
function taskToday(offset=0){const now=new Date();return new Date(Date.UTC(now.getFullYear(),now.getMonth(),now.getDate()+offset)).toISOString().slice(0,10);}
function taskGantt(tasks){return{tasks,anchor:taskToday(),get days(){return Array.from({length:35},(_,i)=>this.dateAt(i));},dateAt(i){const date=new Date(this.anchor+'T00:00:00Z');date.setUTCDate(date.getUTCDate()+i);return date.toISOString().slice(0,10);},shift(n){this.anchor=this.dateAt(n);},get visibleTasks(){const f=this.filters;return this.tasks.filter(t=>(!f.search||t.search.includes(f.search.toLowerCase()))&&(!f.assignees.length||f.assignees.some(id=>t.assignees.includes(String(id))))&&(!f.labels.length||f.labels.some(id=>t.labels.includes(String(id))))&&(!f.due||(f.due==='none'&&!t.due)||(f.due==='overdue'&&t.due&&t.due<taskToday()&&!t.done)||(f.due==='today'&&t.due===taskToday())||(f.due==='week'&&t.due&&t.due>=taskToday()&&t.due<=taskToday(7))));},bar(t){if(!t.start&&!t.due)return null;const start=new Date((t.start||t.due)+'T00:00:00Z'),end=new Date((t.due||t.start)+'T00:00:00Z'),anchor=new Date(this.anchor+'T00:00:00Z');const left=(start-anchor)/86400000,right=(end-anchor)/86400000;if(right<0||left>34)return null;return 'left:'+Math.max(0,left)*28+'px;width:'+Math.max(12,(Math.min(34,right)-Math.max(0,left)+1)*28-4)+'px';}};}
</script>
